"""
crystal.py - crystallography core for the ceramic unit-cell viewer (numpy only).

* Space groups are generated by closing a few generators written in the usual
  "x,y,z" notation, so every Wyckoff orbit is produced by real symmetry operations.
* STRUCTURES holds the structure database (lattice, space group, Wyckoff sites).
"""
import itertools
import math
from functools import lru_cache, reduce

import numpy as np

TOL = 1e-6
N_A = 0.6022            # Avogadro x 1e-24, so  Z*M / (N_A * V[Å^3])  is g/cm^3
BOND_FACTOR = 1.3       # bond cutoff = 1.3 x shortest cation-anion distance of that pair

POSITION_KIND = {3: "Corner", 2: "Edge", 1: "Face", 0: "Interior"}
SUB = str.maketrans("0123456789", "₀₁₂₃₄₅₆₇₈₉")

# --------------------------------------------------------------------------
#  Space-group generators (International Tables, standard settings)
# --------------------------------------------------------------------------
F_CENT = ["x,y+1/2,z+1/2", "x+1/2,y,z+1/2", "x+1/2,y+1/2,z"]
R_CENT = ["x+2/3,y+1/3,z+1/3", "x+1/3,y+2/3,z+2/3"]

PM3M = ["-x,-y,z", "-x,y,-z", "z,x,y", "y,x,-z", "-x,-y,-z"]
FM3M = PM3M + F_CENT
F43M = ["-x,-y,z", "-x,y,-z", "z,x,y", "y,x,z"] + F_CENT
FD3M_O2 = ["-x+3/4,-y+1/4,z+1/2", "-x+1/4,y+1/2,-z+3/4", "z,x,y",
           "y+3/4,x+1/4,-z+1/2", "-x,-y,-z"] + F_CENT          # origin choice 2
P63MC = ["-y,x-y,z", "-x,-y,z+1/2", "-y,-x,z"]
P42MNM = ["-x,-y,z", "-y+1/2,x+1/2,z+1/2", "-x+1/2,y+1/2,-z+1/2", "y,x,-z", "-x,-y,-z"]
R3C_HEX = ["-y,x-y,z", "y,x,-z+1/2", "-x,-y,-z"] + R_CENT
P63MMC = ["-y,x-y,z", "-x,-y,z+1/2", "y,x,-z", "-x,-y,-z"]
P4MM = ["-x,-y,z", "-y,x,z", "x,-y,z"]


def parse_op(s):
    """'-y+1/2,x-y,z' -> (R 3x3 int, t 3-vector)."""
    comps = s.replace(" ", "").split(",")

    def ev(c, x, y, z):
        return float(eval(c, {"__builtins__": {}}, {"x": x, "y": y, "z": z}))

    t = np.array([ev(c, 0, 0, 0) for c in comps])
    R = np.zeros((3, 3))
    for j, e in enumerate(np.eye(3)):
        R[:, j] = np.array([ev(c, *e) for c in comps]) - t
    return np.rint(R).astype(int), t


def _norm_t(t):
    return np.mod(np.round(t, 8), 1.0)


def _op_key(R, t):
    return tuple(R.ravel()) + tuple(np.round(_norm_t(t), 5) + 0.0)


@lru_cache(maxsize=None)
def group_ops(gens):
    """Close the generators into the full list of operations (translations mod 1)."""
    gen_ops = [parse_op(g) for g in gens]
    ident = (np.eye(3, dtype=int), np.zeros(3))
    group = {_op_key(*ident): ident}
    frontier = [ident]
    while frontier:
        new = []
        for Ra, ta in frontier:
            for Rg, tg in gen_ops:
                R = Rg @ Ra
                t = _norm_t(Rg @ ta + tg)
                k = _op_key(R, t)
                if k not in group:
                    group[k] = (R, t)
                    new.append((R, t))
        frontier = new
        if len(group) > 1000:
            raise RuntimeError("space-group closure did not terminate – check generators")
    return list(group.values())


# --------------------------------------------------------------------------
#  Geometry helpers
# --------------------------------------------------------------------------
def cell_matrix(a, b, c, al, be, ga):
    """Rows are the lattice vectors a, b, c (a along x, b in the xy plane)."""
    al, be, ga = (math.radians(v) for v in (al, be, ga))
    cx_ = c * math.cos(be)
    cy_ = c * (math.cos(al) - math.cos(be) * math.cos(ga)) / math.sin(ga)
    cz_ = math.sqrt(max(c * c - cx_ * cx_ - cy_ * cy_, 0.0))
    return np.array([[a, 0, 0], [b * math.cos(ga), b * math.sin(ga), 0], [cx_, cy_, cz_]])


def orbit(xyz, ops):
    seen = {}
    x = np.asarray(xyz, float)
    for R, t in ops:
        p = np.mod(np.round(R @ x + t, 8), 1.0)
        seen.setdefault(tuple(np.round(p, 5) + 0.0), p)
    return np.array(list(seen.values()))


OFFSETS = np.array(list(itertools.product((-1, 0, 1), repeat=3)), float)


def images(orb):
    """All periodic images with offsets -1, 0, +1 along each axis."""
    return (orb[None, :, :] + OFFSETS[:, None, :]).reshape(-1, 3)


def n_boundary(p):
    p = np.asarray(p)
    return int(np.sum((np.abs(p) < TOL) | (np.abs(p - 1) < TOL)))


def share(p):
    return 0.5 ** n_boundary(p)


def images_around(orb, p):
    """Periodic images of the orbit points that surround fractional position p (robust for any p,
    including positions outside [0,1) such as atoms of a hexagonal prism)."""
    o = orb + np.round(np.asarray(p, float) - orb)
    return (o[None, :, :] + OFFSETS[:, None, :]).reshape(-1, 3)


# --- hexagonal prism (the "proper" hcp cell = 3 rhombic cells, hexagon centred on the origin) ---
HEX_ANGLES = np.radians(np.arange(6) * 60.0 + 30.0)     # outward normals of the six lateral faces
OFFSETS_WIDE = np.array(list(itertools.product(range(-2, 3), repeat=3)), float)


def hex_mask(P, M, tol=1e-6):
    """Which fractional points lie inside (or on) the hexagonal prism: hexagon with vertices at
    ±a, ±b, ±(a+b) around the origin, height c."""
    P = np.atleast_2d(P)
    cart = P @ M
    ap = M[0, 0] * math.sqrt(3) / 2
    ok = np.ones(len(P), bool)
    for th in HEX_ANGLES[:3]:
        ok &= np.abs(cart[:, 0] * math.cos(th) + cart[:, 1] * math.sin(th)) <= ap + tol
    return ok & (P[:, 2] > -tol) & (P[:, 2] < 1 + tol)


def n_contacts(p, shape="cell", M=None):
    """Number of cell boundary faces the point touches (0 interior, 1 face, 2 edge, 3 corner)."""
    p = np.asarray(p, float)
    if shape != "hex":
        return n_boundary(p)
    cart = p @ M
    ap = M[0, 0] * math.sqrt(3) / 2
    # six lateral faces = three normals, each tested with both signs
    lateral = sum(abs(s * (cart[0] * math.cos(th) + cart[1] * math.sin(th)) - ap) < 1e-5
                  for th in HEX_ANGLES[:3] for s in (1, -1))
    z = int(abs(p[2]) < TOL or abs(p[2] - 1) < TOL)
    return lateral + z


def share_in(p, shape="cell", M=None):
    """Fraction of the atom that belongs to this cell (1/8 corner ... 1 interior; hexagon vertex = 1/3)."""
    p = np.asarray(p, float)
    if shape != "hex":
        return share(p)
    cart = p @ M
    ap = M[0, 0] * math.sqrt(3) / 2
    lateral = sum(abs(s * (cart[0] * math.cos(th) + cart[1] * math.sin(th)) - ap) < 1e-5
                  for th in HEX_ANGLES[:3] for s in (1, -1))
    h = {0: 1.0, 1: 0.5, 2: 1 / 3}[min(lateral, 2)]
    z = 0.5 ** int(abs(p[2]) < TOL or abs(p[2] - 1) < TOL)
    return h * z


def hex_prism_vertices(M):
    """Bottom (z=0) and top hexagon vertices in Cartesian coordinates, counter-clockwise."""
    a = M[0, 0]
    ang = np.radians(np.arange(6) * 60.0)
    bot = np.stack([a * np.cos(ang), a * np.sin(ang), np.zeros(6)], 1)
    return bot, bot + M[2]


@lru_cache(maxsize=None)
def unit_sphere(n=14):
    th = np.linspace(0, np.pi, n)
    ph = np.linspace(0, 2 * np.pi, 2 * n, endpoint=False)
    m = len(ph)
    T, P = np.meshgrid(th, ph, indexing="ij")
    verts = np.stack([np.sin(T) * np.cos(P), np.sin(T) * np.sin(P), np.cos(T)], -1).reshape(-1, 3)
    tris = []
    for i in range(n - 1):
        for j in range(m):
            a, b = i * m + j, i * m + (j + 1) % m
            c, d = (i + 1) * m + j, (i + 1) * m + (j + 1) % m
            tris += [(a, b, c), (b, d, c)]
    return verts, np.array(tris)


def _dist(A, B):
    return np.linalg.norm(A[:, None, :] - B[None, :, :], axis=2)


# --------------------------------------------------------------------------
#  Building a structure
# --------------------------------------------------------------------------
def build(struct_name, mat_name, shift=False, slider=None, shape="cell"):
    """shape = "cell" (conventional/rhombic cell) or "hex" (hexagonal prism, hexagonal lattices only)."""
    S = STRUCTURES[struct_name]
    m = S["materials"][mat_name]
    if shape == "hex" and cell_kind(m["cell"]) != "hexagonal":
        shape = "cell"
    ops = group_ops(tuple(m.get("gens", S["gens"])))
    params = dict(m.get("params", {}))
    if slider is not None and "slider" in m:
        params[m["slider"]["key"]] = slider
    M = cell_matrix(*m["cell"])

    def make(entry):
        site = entry["site"]
        xyz = site(params) if callable(site) else site
        orb = orbit(xyz, ops)
        if shift:
            orb = np.mod(np.round(orb + 0.5, 8), 1.0)
        d = {k: v for k, v in entry.items() if k != "site"}
        if shape == "hex":
            cand = (orb[None, :, :] + OFFSETS_WIDE[:, None, :]).reshape(-1, 3)
            inside = hex_mask(cand, M)
            drawn = cand[inside].copy()
            drawn[:, 2] = np.clip(drawn[:, 2], 0, 1)
        else:
            cand = images(orb)
            inside = np.all((cand > -TOL) & (cand < 1 + TOL), axis=1)
            drawn = np.clip(cand[inside], 0, 1)
        d.update(orbit=orb, mult=len(orb), drawn=drawn, ghost=cand[~inside])
        return d

    species = [make(e) for e in m["species"]]
    vacant = [make(e) for e in m.get("vacant", S.get("vacant", []))]

    n = len(species)
    cut = np.zeros((n, n))
    dmin = np.zeros((n, n))
    for i in range(n):
        for j in range(n):
            if species[i]["role"] != species[j]["role"]:
                dmin[i, j] = _dist(species[i]["orbit"] @ M, images(species[j]["orbit"]) @ M).min()
    # A cation-anion pair is bonded if closer than 1.3 x the cation's shortest bond to ANY anion
    # species (so far-away anion sites never get an inflated cutoff).
    for i in range(n):
        if species[i]["role"] == "cation":
            shortest = min(dmin[i, j] for j in range(n) if species[j]["role"] == "anion")
            for j in range(n):
                if species[j]["role"] == "anion":
                    cut[i, j] = cut[j, i] = BOND_FACTOR * shortest

    cn = []
    for i, si in enumerate(species):
        p = si["orbit"][0] @ M
        partners, dists = {}, []
        for j, sj in enumerate(species):
            if sj["role"] == si["role"]:
                continue
            dd = np.linalg.norm(images(sj["orbit"]) @ M - p, axis=1)
            sel = dd[dd < cut[i, j] + 1e-6]
            if len(sel):
                partners[sj["label"]] = len(sel)
                dists += list(sel)
        cn.append(dict(cn=len(dists), dmin=min(dists) if dists else 0.0,
                       dmean=float(np.mean(dists)) if dists else 0.0, partners=partners))

    # host = the species whose lattice defines the "holes": the anion array unless the material says otherwise
    host = None
    if m.get("host"):
        host = next((i for i, s in enumerate(species) if s["label"] == m["host"]), None)
    if host is None:
        an_idx = [i for i, s in enumerate(species) if s["role"] == "anion"]
        host = max(an_idx, key=lambda i: species[i]["mult"]) if an_idx else None

    return dict(struct=struct_name, material=mat_name, M=M, cell=m["cell"], species=species, shape=shape, host=host,
                zfac=3 if shape == "hex" else 1,
                vacant=vacant, cut=cut, dmin=dmin, cn=cn, nops=len(ops),
                sg=m.get("sg", S["sg"]), pearson=m.get("pearson", S["pearson"]),
                volume=abs(np.linalg.det(M)))


def formula_and_z(B):
    counts = {}
    for s in B["species"]:
        counts[s["el"]] = counts.get(s["el"], 0) + s["mult"]
    z = reduce(math.gcd, counts.values())
    f = "".join(el + (str(n // z).translate(SUB) if n // z > 1 else "") for el, n in counts.items())
    return f, z


def density(B):
    mass = sum(s["mult"] * s["mass"] for s in B["species"])
    return mass / (N_A * B["volume"])


def lattice_string(cell):
    a, b, c, al, be, ga = cell
    if abs(a - b) < 1e-9 and abs(a - c) < 1e-9 and al == be == ga == 90:
        return f"a = {a:.3f} Å"
    if abs(a - b) < 1e-9:
        return f"a = {a:.3f}, c = {c:.3f} Å"
    return f"a = {a:.3f}, b = {b:.3f}, c = {c:.3f} Å"


def bonds(B, visible, ghosts=False):
    """Bond segments between drawn atoms (and optionally to periodic images outside the cell)."""
    M, sp, cut = B["M"], B["species"], B["cut"]
    segs, gsegs, gatoms = [], [], {}
    for i, si in enumerate(sp):
        if si["role"] != "cation" or not si["bond"] or i not in visible:
            continue
        for j, sj in enumerate(sp):
            if sj["role"] != "anion" or j not in visible:
                continue
            Di, Dj = si["drawn"] @ M, sj["drawn"] @ M
            ii, jj = np.where(_dist(Di, Dj) < cut[i, j] + 1e-6)
            segs += [(Di[a], Dj[b]) for a, b in zip(ii, jj)]
            if ghosts:
                Gj = sj["ghost"] @ M
                ii, jj = np.where(_dist(Di, Gj) < cut[i, j] + 1e-6)
                gsegs += [(Di[a], Gj[b]) for a, b in zip(ii, jj)]
                if len(jj):
                    gatoms.setdefault(j, []).append(sj["ghost"][np.unique(jj)])
                Gi = si["ghost"] @ M
                ii, jj = np.where(_dist(Gi, Dj) < cut[i, j] + 1e-6)
                gsegs += [(Gi[a], Dj[b]) for a, b in zip(ii, jj)]
                if len(ii):
                    gatoms.setdefault(i, []).append(si["ghost"][np.unique(ii)])
    for k in list(gatoms):
        arr = np.vstack(gatoms[k])
        _, idx = np.unique(np.round(arr, 5), axis=0, return_index=True)
        gatoms[k] = arr[np.sort(idx)]
    return segs, gsegs, gatoms


def coordination_shell(B, i):
    """Centre (most interior atom of species i) and its nearest-neighbour shell, Cartesian."""
    M, sp = B["M"], B["species"]
    drawn = sp[i]["drawn"]
    c = drawn[int(np.argmin([n_contacts(p, B['shape'], B['M']) for p in drawn]))]
    cc = c @ M
    pts = []
    for j, sj in enumerate(sp):
        if sj["role"] == sp[i]["role"]:
            continue
        P = images_around(sj["orbit"], c) @ M
        pts.append(P[np.linalg.norm(P - cc, axis=1) < B["cut"][i, j] + 1e-6])
    return c, cc, np.vstack(pts)


# --------------------------------------------------------------------------
#  Crystallographic directions  [uvw]
# --------------------------------------------------------------------------
def cell_kind(cell):
    a, b, c, al, be, ga = cell
    right = al == 90 and be == 90 and ga == 90
    if right and abs(a - b) < 1e-9 and abs(a - c) < 1e-9:
        return "cubic"
    if right and abs(a - b) < 1e-9:
        return "tetragonal"
    if abs(a - b) < 1e-9 and al == 90 and be == 90 and ga == 120:
        return "hexagonal"
    return "other"


def reduce_direction(v, tol=0.02, kmax=6):
    """Fractional vector -> smallest integer triple with the same direction, or None if the
    direction is not a simple low-index one (e.g. refined internal coordinates like 0.1688)."""
    v = np.asarray(v, float)
    m = np.abs(v).max()
    if m < 1e-9:
        return None
    r = v / m
    for k in range(1, kmax + 1):
        s = r * k
        if np.all(np.abs(s - np.rint(s)) < tol):
            ints = [int(x) for x in np.rint(s)]
            g = reduce(math.gcd, [abs(x) for x in ints])
            return tuple(x // g for x in ints)
    return None


def _idx(n):
    return str(abs(n)) + ("̄" if n < 0 else "")      # 1̄ style bar notation


def hex4(d):
    u, v, w = d
    U, V, T, W = 2 * u - v, 2 * v - u, -(u + v), 3 * w
    g = reduce(math.gcd, [abs(x) for x in (U, V, T, W)]) or 1
    return tuple(x // g for x in (U, V, T, W))


def fmt_dir(d, kind):
    if kind == "hexagonal":
        return "[" + "".join(_idx(x) for x in hex4(d)) + "]"
    return "[" + "".join(_idx(x) for x in d) + "]"


def fmt_family(d, kind):
    if kind == "cubic":
        f = sorted((abs(x) for x in d), reverse=True)
    elif kind == "tetragonal":
        f = sorted((abs(d[0]), abs(d[1])), reverse=True) + [abs(d[2])]
    else:
        return None
    return "⟨" + "".join(str(x) for x in f) + "⟩"


def position_direction(p, B):
    """HTML lines: direction from the cell origin to the atom."""
    kind = cell_kind(B["cell"])
    r = float(np.linalg.norm(np.asarray(p) @ B["M"]))
    if r < 1e-6:
        return ["<b>Direction from origin:</b> atom sits at the origin"]
    d = reduce_direction(p)
    if d is None:
        pn = np.asarray(p)
        return [f"<b>Direction from origin:</b> not a low-index direction "
                f"(≈ [{pn[0]:.3f} {pn[1]:.3f} {pn[2]:.3f}] in fractional units)",
                f"distance from origin {r:.3f} Å"]
    fam = fmt_family(d, kind)
    s = f"<b>Direction from origin:</b> {fmt_dir(d, kind)}"
    if fam:
        s += f" &nbsp;family {fam}"
    if kind == "hexagonal":
        s += f" &nbsp;(3-index [{''.join(_idx(x) for x in d)}])"
    return [s, f"distance from origin {r:.3f} Å"]


def bond_directions(B, i, p, max_lines=6):
    """HTML lines: directions (and counts) of the bonds leaving atom p of species i."""
    M, sp_, cut = B["M"], B["species"], B["cut"]
    kind = cell_kind(B["cell"])
    Minv = np.linalg.inv(M)
    pc = np.asarray(p) @ M
    groups = {}
    for j, sj in enumerate(sp_):
        if sj["role"] == sp_[i]["role"] or cut[i, j] <= 0:
            continue
        P = images_around(sj["orbit"], p) @ M
        dist = np.linalg.norm(P - pc, axis=1)
        for q, dd in zip(P[dist < cut[i, j] + 1e-6], dist[dist < cut[i, j] + 1e-6]):
            d = reduce_direction((q - pc) @ Minv)
            if d is None:
                key = (sj["label"], "irregular", None, round(float(dd), 2))
            else:
                fam = fmt_family(d, kind)
                key = (sj["label"], fam if fam else fmt_dir(d, kind), fam is not None, round(float(dd), 2))
            groups.setdefault(key, []).append(float(dd))
    if not groups:
        return []
    lines = ["<b>Bond directions from this atom:</b>"]
    items = sorted(groups.items(), key=lambda kv: (kv[0][3], kv[0][0]))
    for (lab, dirs, is_fam, _), ds in items[:max_lines]:
        name = "non-low-index directions" if dirs == "irregular" else dirs
        lines.append(f"→ {lab} along {name} ×{len(ds)} at {np.mean(ds):.3f} Å")
    if len(items) > max_lines:
        lines.append(f"… and {len(items) - max_lines} more bond group(s)")
    return lines


# --------------------------------------------------------------------------
#  Site geometry (tetrahedral, octahedral, ...) computed from neighbour positions
# --------------------------------------------------------------------------
def classify_shell(vecs, dists=None):
    """Name the coordination polyhedron formed by neighbour vectors (Cartesian, centred on the site)."""
    vecs = np.asarray(vecs, float)
    n = len(vecs)
    if n == 0:
        return "no neighbours"
    U = vecs / np.linalg.norm(vecs, axis=1)[:, None]
    cs = (U @ U.T)[np.triu_indices(n, 1)] if n > 1 else np.array([])
    opp = int(np.sum(cs < -0.9))                      # near-opposite pairs (angle > 154°)
    if n == 1:
        name = "terminal (1-fold)"
    elif n == 2:
        name = "linear" if opp else "bent"
    elif n == 3:
        # planar if the three unit vectors span (almost) no volume; angles need not be 120° (rutile O: 99/131/131°)
        name = "trigonal planar" if abs(np.linalg.det(U)) < 0.2 else "trigonal pyramidal"
    elif n == 4:
        if opp >= 2:
            name = "square planar"
        elif cs.max() < 0.5 and cs.min() > -0.9:
            name = "tetrahedral"
        else:
            name = "4-coordinate (irregular)"
    elif n == 5:
        name = {1: "trigonal bipyramidal", 2: "square pyramidal"}.get(opp, "5-coordinate (irregular)")
    elif n == 6:
        name = "octahedral" if opp >= 3 else ("trigonal prismatic" if opp == 0 else "6-coordinate (irregular)")
    elif n == 8:
        name = "cubic" if opp == 4 else "8-coordinate (e.g. square antiprism)"
    elif n == 12:
        name = "cuboctahedral" if opp == 6 else "12-coordinate"
    else:
        name = f"{n}-coordinate"
    if dists is not None and n > 1:
        d = np.asarray(dists)
        if (d.max() - d.min()) / d.mean() > 0.03 and "irregular" not in name:
            name += " (distorted)"
    return name


def _shell_vectors(B, i, p):
    """Bonded neighbours of atom p (species i): list of (partner label, Cartesian vector, distance)."""
    M, sp_, cut = B["M"], B["species"], B["cut"]
    pc = np.asarray(p) @ M
    out = []
    for j, sj in enumerate(sp_):
        if sj["role"] == sp_[i]["role"] or cut[i, j] <= 0:
            continue
        P = images_around(sj["orbit"], p) @ M
        dd = np.linalg.norm(P - pc, axis=1)
        for q, d in zip(P[dd < cut[i, j] + 1e-6], dd[dd < cut[i, j] + 1e-6]):
            out.append((sj["label"], q - pc, float(d)))
    return out


def site_geometry(B, i, p=None):
    """(name, CN, [(label, count, mean distance), ...]) for species i (at p, default most interior atom)."""
    if p is None:
        drawn = B["species"][i]["drawn"]
        p = drawn[int(np.argmin([n_contacts(q, B['shape'], B['M']) for q in drawn]))]
    sh = _shell_vectors(B, i, p)
    if not sh:
        return "no neighbours", 0, []
    name = classify_shell([v for _, v, _ in sh], [d for _, _, d in sh])
    groups = {}
    for lab, _, d in sh:
        groups.setdefault(lab, []).append(d)
    return name, len(sh), [(k, len(v), float(np.mean(v))) for k, v in groups.items()]


def site_description(B, i, p):
    """HTML lines for the hover card: which kind of site this atom occupies."""
    name, cn, groups = site_geometry(B, i, p)
    lines = [f"<b>Site:</b> {name} · CN {cn}"]
    lines += [f"{n} × {lab} at {d:.3f} Å" for lab, n, d in groups]
    return lines


def vacant_description(B, p, max_lines=3):
    """HTML lines for an empty interstitial site. The hole type is always stated for the HOST lattice
    (the close-packed array, normally the anions), so an octahedral hole is never reported as tetrahedral
    just because it looks different from another sublattice."""
    M, sp_ = B["M"], B["species"]
    pc = np.asarray(p) @ M

    def view(j):
        P = images_around(sp_[j]["orbit"], p) @ M
        dd = np.linalg.norm(P - pc, axis=1)
        d0 = dd.min()
        sel = dd < d0 * 1.08
        return d0, int(sel.sum()), classify_shell(P[sel] - pc, dd[sel])

    h = B.get("host")
    lines = ["<b>Empty interstitial site</b>"]
    if h is not None:
        d0, n, cls = view(h)
        lines.append(f"<b>{cls.split(' (')[0].capitalize()} hole</b> in the {sp_[h]['label']} array:")
        lines.append(f"{n} × {sp_[h]['label']} at {d0:.3f} Å")
        return lines
    found = []
    for j, sj in enumerate(sp_):
        d0, n, cls = view(j)
        found.append((d0, sj["label"], n, cls))
    nearest = min(f[0] for f in found)
    found = [f for f in sorted(found) if f[0] < 1.4 * nearest and f[2] >= 3][:max_lines]
    lines += [f"{n} × {lab} at {d:.3f} Å → {cls}" for d, lab, n, cls in found]
    return lines


def direction_line(B, uvw, visible):
    """Line [uvw] through the cell, plus the atoms lying on it per repeat distance."""
    M = B["M"]
    vec = np.array(uvw, float)
    g = reduce(math.gcd, [abs(int(x)) for x in uvw]) or 1
    vec = vec / g
    L = float(np.linalg.norm(vec @ M))
    if B.get("shape") == "hex":
        # prism: line starts at the origin (centre of the bottom face) and runs to the prism surface
        start = np.array([0.0, 0.0, 1.0 if vec[2] < 0 else 0.0])
        vc = vec @ M
        ap = M[0, 0] * math.sqrt(3) / 2
        tmax = min([ap / abs(vc[0] * math.cos(th) + vc[1] * math.sin(th)) for th in HEX_ANGLES[:3]
                    if abs(vc[0] * math.cos(th) + vc[1] * math.sin(th)) > 1e-9] + [1e9])
        if abs(vec[2]) > 0:
            tmax = min(tmax, 1.0 / abs(vec[2]))
        end = start + vec * tmax
    else:
        start = np.where(vec < 0, 1.0, 0.0)
        end = start + vec / np.abs(vec).max()
    offs = np.array(list(itertools.product(range(-3, 4), repeat=3)), float)
    per_species, total = {}, 0
    for k, s in enumerate(B["species"]):
        if k not in visible:
            continue
        P = (s["orbit"][None, :, :] + offs[:, None, :]).reshape(-1, 3) - start
        t = P @ vec / float(vec @ vec)
        perp = P - np.outer(t, vec)
        on = (np.linalg.norm(perp @ M, axis=1) < 1e-4) & (t > -1e-6) & (t < 1 - 1e-6)
        n = len(np.unique(np.round(t[on], 5)))
        if n:
            per_species[s["label"]] = n
            total += n
    return dict(start=start @ M, end=end @ M, L=L, per_species=per_species, total=total,
                dens=total / L * 10.0, vec=tuple(int(x) for x in vec))


