def sp(label, el, role, r, color, mass, site, wy, bond=True, geom=""):
    return dict(label=label, el=el, role=role, radius=r, color=color, mass=mass,
                site=site, wy=wy, bond=bond, geom=geom)


def vac(label, site, wy, symbol):
    return dict(label=label, el="", role="vacant", radius=0.0, color="#e67e22", mass=0.0,
                site=site, wy=wy, bond=False, geom="", symbol=symbol)


